<script setup>
import { computed, onMounted, ref } from 'vue'
import { apiGet } from '../api'
import { company } from '../company'
import { recordRoute } from '../discovery'
import { deskLink } from '../format'
const props = defineProps({ search: {default:''} })
const reports = ref([]), selected = ref(null), filters = ref({}), data = ref(null), error = ref(''), busy = ref(false)
const matches = computed(()=>reports.value.filter(r=>r.name.toLowerCase().includes(props.search.toLowerCase())))
const visibleColumns = computed(()=>(data.value?.columns ?? []).filter(c=>!c.hidden))
let generation = 0
function choose(r) {generation++;busy.value=false;selected.value=r;filters.value=Object.fromEntries(r.filters.map(f=>[f,f==='company' ? company.value : new Date().toISOString().slice(0,10)]));data.value=null;error.value=''}
function changed(){generation++;busy.value=false;data.value=null}
async function run(append=false){const id=++generation;busy.value=true;error.value='';try{const result=(await apiGet('/api/method/sidra_realestate.api.native_reports.run_report',{name:selected.value.name,filters:filters.value,start:append ? data.value.rows.length : 0})).message;if(id===generation)data.value={...result,rows:append ? [...data.value.rows,...result.rows] : result.rows}}catch(e){if(id===generation)error.value=e.message}finally{if(id===generation)busy.value=false}}
const exportLink = computed(()=>'/api/method/sidra_realestate.api.native_reports.export_report?'+new URLSearchParams({name:selected.value?.name ?? '',filters:JSON.stringify(filters.value)}))
function target(c,row){const type=c.fieldtype==='Dynamic Link' ? row[c.options] : c.options; return {route:recordRoute(type,row[c.fieldname]),href:deskLink(type,row[c.fieldname])}}
onMounted(async()=>{try{reports.value=(await apiGet('/api/method/sidra_realestate.api.native_reports.catalogue')).message}catch(e){error.value=e.message}})
</script>
<template><section><h2>Accounting reports</h2><div class="buttons"><button v-for="r in matches" :key="r.name" class="bj-btn" @click="choose(r)">{{r.name}}</button></div><p v-if="!reports.length && !error">No supported accounting reports are available to your role.</p><p v-if="error" role="alert">{{error}}</p><div v-if="selected" class="bj-card"><h3>{{selected.name}}</h3><form @submit.prevent="run()"><label v-for="f in selected.filters" :key="f">{{ f.replaceAll('_',' ') }}<input v-model="filters[f]" class="bj-input" :type="f==='company' ? 'text' : 'date'" required @input="changed" /></label><button class="bj-btn" :disabled="busy">Run report</button></form><a v-if="data && selected.can_export" class="bj-btn" :href="exportLink">Export matching rows (CSV)</a><p class="bj-muted">Native accounting figures. Accounting document links open in Desk for finance staff.</p><div class="table"><table v-if="data"><thead><tr><th v-for="c in visibleColumns" :key="c.fieldname">{{c.label}}</th></tr></thead><tbody><tr v-for="(row,i) in data.rows" :key="i"><td v-for="c in visibleColumns" :key="c.fieldname"><template v-if="['Link','Dynamic Link'].includes(c.fieldtype) && row[c.fieldname]"><RouterLink v-if="target(c,row).route" :to="target(c,row).route">{{row[c.fieldname]}}</RouterLink><a v-else-if="target(c,row).href" :href="target(c,row).href">{{row[c.fieldname]}}</a><span v-else>{{row[c.fieldname]}}</span></template><span v-else>{{row[c.fieldname] ?? '—'}}</span></td></tr></tbody></table></div><p v-if="data && !data.rows.length">No matching entries.</p><button v-if="data?.has_more" class="bj-btn" :disabled="busy" @click="run(true)">Load more</button><p v-if="busy" role="status">Loading report…</p></div></section></template>
<style scoped>h2 { margin:24px 0 12px;font-size:17px;font-weight:600 } h3 { font-size:16px;font-weight:600 }.buttons,form { display:flex;gap:12px;flex-wrap:wrap;margin:16px 0;align-items:end } label { display:grid;gap:8px;text-transform:capitalize } .table { overflow:auto;margin:16px 0 } table { border-collapse:collapse;width:100% } th,td { text-align:left;padding:10px;border-bottom:1px solid var(--bj-line);white-space:nowrap }</style>
